#include "netpulse/net.hpp"
#include "netpulse/protocol.hpp"
#include <iostream>
#include <string>
#include <stdexcept>
#include <cstdlib>
using namespace netpulse;
static void help(){std::cout<<"NetPulse — C++ TCP/UDP Network Communication and Performance Analyzer\n\nUsage:\n  netpulse server --protocol tcp|udp [--host 127.0.0.1] [--port N]\n  netpulse client --protocol tcp|udp --host IPv4 --port N [--timeout-ms N]\n  netpulse benchmark --protocol tcp|udp --host IPv4 --port N [--count N] [--size N] [--interval-ms N] [--timeout-ms N] [--output PATH]\n  netpulse --help\n\nOptions: --host IPv4 --port 1..65535 --count 1..10000000 --size 0..60000 --timeout-ms N --interval-ms N --duration N (reserved) --clients N (currently 1) --output PATH\nServer binds to loopback by default. Use --host 0.0.0.0 only when intentionally accepting connections on all IPv4 interfaces.\n";}
int main(int argc,char**argv){if(argc<2){help();return 0;}std::string command=argv[1];if(command=="--help"||command=="-h"||command=="help"){help();return 0;}Options o;try{for(int i=2;i<argc;++i){std::string k=argv[i];if(k=="--help"||k=="-h"){help();return 0;}if(i+1>=argc)throw std::runtime_error("missing value for "+k);std::string v=argv[++i];if(k=="--protocol")o.protocol=v;else if(k=="--host")o.host=v;else if(k=="--port")o.port=std::stoi(v);else if(k=="--count")o.count=std::stoi(v);else if(k=="--size")o.size=std::stoi(v);else if(k=="--duration")o.duration=std::stoi(v);else if(k=="--interval-ms")o.interval_ms=std::stoi(v);else if(k=="--timeout-ms")o.timeout_ms=std::stoi(v);else if(k=="--clients")o.clients=std::stoi(v);else if(k=="--output")o.output=v;else throw std::runtime_error("unknown option: "+k);}if(o.port<1||o.port>65535)throw std::runtime_error("port must be in 1..65535");if(o.timeout_ms<1||o.timeout_ms>600000)throw std::runtime_error("timeout-ms must be in 1..600000");if(o.interval_ms<0||o.interval_ms>600000)throw std::runtime_error("interval-ms must be in 0..600000");if(o.duration<0||o.duration>86400)throw std::runtime_error("duration must be in 0..86400");if(o.size<0||static_cast<std::size_t>(o.size)>kMaxPayload)throw std::runtime_error("size must be in 0..60000");if(command=="server")return run_server(o);if(command=="client")return run_client(o);if(command=="benchmark")return run_benchmark(o);throw std::runtime_error("unknown command: "+command);}catch(const std::exception&e){std::cerr<<"[ERROR] "<<e.what()<<"\nUse --help for usage.\n";return 2;}}
